import re

pattern = re.compile(r'([A-Za-z0-9+#./ _-]+?)\s*\(([\d,]+)\s*bytes\)')

def main_language(desc):
    if not isinstance(desc, str):
        return None
    matches = pattern.findall(desc)
    if not matches:
        return None
    best_lang, best_bytes = None, -1
    for lang, b in matches:
        try:
            bn = int(b.replace(',', ''))
        except:
            continue
        if bn > best_bytes:
            best_bytes = bn
            best_lang = lang.strip()
    return best_lang

lang_subset['main_language'] = lang_subset['language_description'].apply(main_language)
print(lang_subset[['repo_name','main_language']].to_string())
